// mapList
// Known as map
export const mapList =
  <T1, T2>(f: (x: T1) => T2): ((y: List<T1>) => List<T2>) =>
  (l: List<T1>) =>
    bindList(l, (x: T1) => wrapList(f(x)));

// Examples
