export const chainList =
  <T1, T2>(f: (x: T1) => List<T2>): ((y: List<T1>) => List<T2>) =>
  (y: List<T1>) => bindList(y, f);

export const chainOption =
  <T1, T2>(f: (x: T1) => Option<T2>): ((y: Option<T1>) => Option<T2>) =>
  (y: Option<T1>) => bindOption(y, f);
```

